from addlib import *
def sk(w='100%',h='1.5rem'): return f'<span class="skeleton" style="display:block;width:{w};height:{h}"></span>'
def wtw(body,min_=True):
    st=' style="min-height:10.25rem"' if min_ else ''
    return (f'<section class="where-to-watch"><div class="where-to-watch__panel" data-open="true"{st}><div class="where-to-watch__head"><div class="where-to-watch__title"><h2>{L("details.watch.heading")}</h2></div></div>'
            f'<div class="where-to-watch__body">{body}</div></div></section>')
def prov(n): return '<ul class="where-to-watch__list">'+''.join(f'<li>{sk("60%")}</li>' for _ in range(n))+'</ul>'
LOAD=f'<div style="display:flex;flex-direction:column;gap:var(--sp-3)" role="status" aria-label="{L("details.watch.loading")}">{sk("100%","3.25rem")}{sk("70%")}{sk("55%")}{sk("65%")}</div>'
ERR=f'<div class="load-error load-error--inline" role="alert">{icon("triangle-alert",24,None,"load-error__icon")}<div class="load-error__text"><strong>{L("loadError.title")}</strong><p>{L("details.watch.error")}</p></div>{btn("panel",L("common.retry"),"sm","","rotate-ccw")}</div>'
DATA=f'<div style="display:flex;flex-direction:column;gap:var(--sp-3)">{sk("100%","3.25rem")}{sk("70%")}{sk("55%")}{sk("65%")}</div>'
add('Pagina Film',
 block('Decisione · “Dove guardare” in caricamento: dimensioni fisse',DECI,'Oggi lo stato di caricamento è una riga di testo (<code>&lt;p role="status"&gt;</code>, WhereToWatch.tsx r.49): il riquadro nasce basso e si allarga quando arrivano i dati. <b>Decisione:</b> il riquadro ha un\'altezza minima uguale in tutti gli stati (caricamento, errore, vuoto, con dati) pari a: intestazione + select (3,25rem) + 3 righe di provider (1,5rem, <code>--sp-3</code> di distanza): <b>10,25rem</b> (<code>WhereToWatch.less</code> r.15-21: <code>.where-to-watch__loading</code>, <code>.where-to-watch .load-error</code>, <code>.where-to-watch__panel[data-open="true"]</code>). Cresce solo se i provider sono di più, non si rimpicciolisce mai. La larghezza è quella della colonna in ogni stato. Lo scheletro segue la regola esistente: compare dopo <code>--delay-pending</code> (200 ms), poi pulse; sotto i 200 ms non si vede nulla e non c\'è salto. L\'annuncio resta <code>role="status"</code> con <code>details.watch.loading</code> come etichetta.',
  '<div class="dc-row">'+fr('dark','420px',wtw(LOAD),'Caricamento · altezza minima fissa','0')+fr('dark','420px',wtw(ERR),'Errore · stessa altezza','0')+'</div>'+txt([('details.watch.loading',T(*[L('details.watch.loading',l) for l in LANGS]))])
  +pd([['Caricamento','<code>&lt;p role="status"&gt;</code> con testo; il riquadro cambia altezza','scheletro (select + 3 righe) con altezza minima uguale a tutti gli stati','WhereToWatch.tsx r.49; WhereToWatch.less (.where-to-watch__panel)'],['Altezza degli stati','diversa per stato','<code>min-height: 10.25rem</code> comune; mai minore','WhereToWatch.less r.53-59']])),
 block('Decisione · “Dove guardare” senza rete o dati non recuperati',DECI,'Oggi l\'errore è un <code>&lt;div role="alert"&gt;</code> con un pulsante “Riprova” <code>panel</code> e RotateCcw scritti a mano (WhereToWatch.tsx): non usa il componente degli errori. <b>Decisione:</b> si usa <code>LoadError</code> in forma <code>inline</code> (icona <code>triangle-alert</code> 24px, titolo in grassetto <code>loadError.title</code>, riga <code>details.watch.error</code>, pulsante sm con “Riprova” e RotateCcw a sinistra: regola icone), dentro il riquadro con le stesse dimensioni minime. “Riprova” rimette lo scheletro finché non risponde; l\'errore mantiene <code>role="alert"</code>. Senza rete (<code>navigator.onLine</code> falso) il testo è lo stesso: non si inventa un secondo messaggio.',
  '<div class="dc-row">'+fr('dark','420px',wtw(ERR),'Errore · scuro','0')+fr('light','420px',wtw(ERR.replace('btn--panel','btn--soft')),'Errore · chiaro','0')+'</div>'+txt([('loadError.title',T(*[L('loadError.title',l) for l in LANGS])),('details.watch.error',T(*[L('details.watch.error',l) for l in LANGS])),('common.retry',T(*[L('common.retry',l) for l in LANGS]))])
  +pd([['Errore','<code>&lt;div role="alert"&gt;</code> + Riprova scritto a mano','<code>LoadError variant="inline"</code>','WhereToWatch.tsx; LoadError.tsx r.50-58']])),
)
POSTER_ERR=f'<div style="width:12rem;aspect-ratio:2/3"><div class="poster-image"><span class="poster-image__state" role="img" aria-label="{L("details.missing.cover")}">{icon("image-off")}<span class="poster-image__text">{L("details.missing.cover")}</span></span></div></div>'
POSTER_LOAD='<div style="width:12rem;aspect-ratio:2/3"><div class="poster-image"><span class="poster-image__state poster-image__state--loading" role="img" aria-hidden="true">'+icon('loader')+'</span></div></div>'
add('Pagina Film',
 block('Decisione · copertina che non si carica',DECI,'Oggi la pagina usa un <code>&lt;img&gt;</code> semplice: se la rete cade a metà, il browser mostra l\'icona dell\'immagine rotta. La copertina mancante nei dati ha già il suo stato (<code>.film__cover-missing</code>, <code>details.missing.cover</code>, TitleDetailsPanel.tsx r.71-73). <b>Decisione:</b> la copertina usa <code>PosterImage</code> (già usato nelle righe): riquadro 2:3 con fondo piatto <code>--poster-bg</code> subito, spinner dopo <code>--delay-pending</code>, dissolvenza <code>--dur-ui</code> a caricamento riuscito, e in caso di errore di rete lo stesso stato “mancante” (icona <code>image-off</code> + <code>details.missing.cover</code>). Nessun “Riprova” sulla singola immagine: si riprova ricaricando i dati della pagina. Le dimensioni del riquadro sono fisse: nessuno spostamento del testo accanto.',
  '<div class="dc-row">'+fr('light','220px',POSTER_LOAD,'Caricamento · chiaro')+fr('dark','220px',POSTER_ERR,'Errore di rete · scuro')+fr('light','220px',POSTER_ERR,'Errore di rete · chiaro')+'</div>'+txt([('details.missing.cover',T(*[L('details.missing.cover',l) for l in LANGS])),('poster.missing',T(*[L('poster.missing',l) for l in LANGS]))])
  +pd([['Copertina che non si carica','icona dell\'immagine rotta del browser','<code>PosterImage</code>: placeholder, caricamento, errore','TitleDetailsPanel.tsx r.57-75; PosterImage.less']])),
)
def twoblocks(sep):
    s='border-top:1px solid var(--line);padding-top:var(--sp-6);margin-top:var(--sp-6)' if sep else ''
    return (f'<div style="display:flex;flex-direction:column"><section><h2 style="margin:0;font-size:var(--fs-label);font-weight:800">{L("details.director")}</h2><p style="margin:0">Marta Rossi</p></section>'
            f'<section style="{s}"><h2 style="margin:0;font-size:var(--fs-label);font-weight:800">{L("details.cast")}</h2><p style="margin:0">Luca Bianchi, Anna Verdi</p></section></div>')
MISS_B=f'<p class="muted" style="font-size:var(--fs-body)">{L("details.missing.director")}</p>'
MISS_A=f'<p class="muted" style="font-size:var(--fs-label)">{L("details.missing.director")}</p>'
add('Pagina Film',
 block('Decisione · “Regia” e “Cast” su schermo stretto',DECI,'Sotto 40em i due blocchi sono uno sotto l\'altro con lo stesso spazio delle righe interne: si leggono come un solo elenco. <b>Decisione:</b> sono due sezioni distinte: spazio di <code>--sp-6</code> sopra la seconda e una linea sottile <code>--line</code> di 1px a separarle; i titoli <code>h2</code> restano uguali. Da 40em in su (due colonne) la linea non c\'è. I nomi sono segnaposto di esempio.',
  '<div class="dc-row">'+phone(f'<div style="padding:var(--sp-4);background:var(--bg);color:var(--ink)">{twoblocks(False)}</div>','light',200,320,'Prima')+phone(f'<div style="padding:var(--sp-4);background:var(--bg);color:var(--ink)">{twoblocks(True)}</div>','light',220,320,'Dopo')+'</div>'
  +pd([['Separazione Regia / Cast, sotto 40em','nessuna','<code>--sp-6</code> + linea <code>--line</code> 1px','TitleDetailsPanel.less (.film__cast, r.202-209)']])),
 block('Decisione · “Regia non disponibile.”',DECI,'Il testo mancante (<code>details.missing.director</code>, <code>details.missing.cast</code>) usa il corpo di paragrafo (<code>.muted</code> a <code>--fs-body</code>): è più grande del dato che sostituisce e attira più del titolo. <b>Decisione:</b> <code>--fs-label</code> (lo stesso del titolo di blocco), colore <code>--ink-2</code> (<code>.muted</code>), nessun grassetto. Vale anche per cast, trama e trailer mancanti (<code>details.missing.*</code>).',
  '<div class="dc-row">'+fr('light','320px','<h2 style="margin:0;font-size:var(--fs-label);font-weight:800">'+L('details.director')+'</h2>'+MISS_B,'Prima: <code>--fs-body</code>')+fr('light','320px','<h2 style="margin:0;font-size:var(--fs-label);font-weight:800">'+L('details.director')+'</h2>'+MISS_A,'Dopo: <code>--fs-label</code>')+'</div>'
  +txt([('details.missing.director',T(*[L('details.missing.director',l) for l in LANGS])),('details.missing.cast',T(*[L('details.missing.cast',l) for l in LANGS]))])
  +pd([['Corpo del testo mancante','<code>--fs-body</code>','<code>--fs-label</code>','TitleDetailsPanel.tsx,; TitleDetailsPanel.less']])),
)
# ---------- MOTION B4 ----------
CASC=[['Planner','intestazione','0','già nel codice (<code>.site-header</code>)'],['Planner','scheda dei progressi','30','già nel codice'],['Planner','rail, ricerca o barra mobile','60','già nel codice'],['Planner','prossimo da guardare','90','già nel codice'],['Planner','prima fase','120','già nel codice'],['Pagina film','intestazione','0','da aggiungere'],['Pagina film','copertina','30','da aggiungere'],['Pagina film','titolo e metadati','60','da aggiungere'],['Pagina film','Dove guardare','90','da aggiungere'],['Pagina film','trama, poi regia e cast','120 e 150 (tetto)','da aggiungere']]
DEMO='''<style>@keyframes dc-cas{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
.dc-cas>*{padding:var(--sp-3) var(--sp-4);background:var(--surface);border-radius:var(--r-md)}
@media (prefers-reduced-motion:no-preference){.dc-cas>*{animation:dc-cas var(--dur-enter) var(--ease-out) both;animation-delay:min(calc(var(--stagger-step)*var(--i)),var(--stagger-max))}}</style>
<div class="dc-cas" style="display:flex;flex-direction:column;gap:var(--sp-2);max-width:20rem"><div style="--i:0">0 ms · Intestazione</div><div style="--i:1">30 ms · Progressi</div><div style="--i:2">60 ms · Ricerca e filtri</div><div style="--i:3">90 ms · Prossimo da guardare</div><div style="--i:4">120 ms · Prima fase</div></div>'''
add('Motion',
 block('Decisione · ingresso a cascata all\'atterraggio (planner e pagina film)',DECI,'Il codice ha già la cascata: <code>:root[data-intro]</code> (motion.less r.451-476) anima <code>swap-in</code> (dissolvenza e salita di 6px) in <code>--dur-enter</code> sui blocchi della prima schermata del planner, con ritardo <code>min(--stagger-step × --i, --stagger-max)</code> = 30 ms a passo, tetto 150 ms (tokens.less r.184-185). Ma <code>data-intro</code> si accende solo dopo la splash e si toglie dopo ~450 ms: all\'arrivo successivo sul planner, e sempre sulla pagina film, tutto compare di colpo. <b>Decisione:</b> <b>nessun token nuovo</b>. (1) <code>data-intro</code> si imposta a <b>ogni arrivo</b> su planner e pagina film (primo caricamento e navigazione), non solo dopo la splash, e si toglie dopo la fine della cascata (~600 ms); (2) la pagina film entra nella stessa lista di <code>:root[data-intro]</code> con i blocchi della tabella; (3) solo la prima schermata si anima, il resto compare normalmente; (4) la cascata <b>non</b> si ripete cambiando filtro, ordine o aprendo una fase (<code>data-intro</code> è già tolto); (5) <b>movimento ridotto:</b> <code>--stagger-step</code> e <code>--stagger-max</code> valgono 0 (tokens.less r.205-206) e <code>--dur-enter</code> è 80 ms: resta solo la dissolvenza, senza salita né ritardo. La demo qui sotto parte alla visualizzazione.',
  DEMO+tbl(['Pagina','Blocco','Ritardo (ms)','Stato nel codice'],CASC)
  +pd([['Quando parte','solo dopo la splash, una volta (<code>data-intro</code>)','a ogni arrivo su planner e film','motion.less r.451-476; Planner.tsx; AppLayout.tsx'],['Pagina film','nessuna cascata','cascata sui blocchi della prima schermata, stessi token','motion.less (lista di <code>:root[data-intro]</code>); TitleDetailsPanel.tsx'],['Token','—','<code>--stagger-step</code> 30 ms, <code>--stagger-max</code> 150 ms, già esistenti','tokens.less r.184-185, r.205-206'],['Movimento ridotto','—','passo e tetto a 0, <code>--dur-enter</code> 80 ms','tokens.less r.200-206']])),
)
